   124|/**
   125| * Mint a real Supabase session WITHOUT touching the owner's password:
   126| * admin generateLink(magiclink) -> verifyOtp(token_hash) with the anon key.
   127| */
   128|async function mintSessionViaMagicLink(
   129|  adminClient: SupabaseClient,
   130|  email: string,
   131|): Promise<{ ok: boolean; session?: MintedSession; errorMessage?: string }> {
   132|  const supabaseUrl = resolveSupabaseUrl();
   133|  const anonKey = resolveAnonKey();
   134|  if (!anonKey) {
   135|    return { ok: false, errorMessage: 'Supabase anon key is not configured on the backend.' };
   136|  }
   137|
   138|  let tokenHash = '';
   139|  try {
   140|    const { data, error } = await adminClient.auth.admin.generateLink({ type: 'magiclink', email });
   141|    if (error) {
   142|      return { ok: false, errorMessage: `generateLink failed: ${error.message}` };
   143|    }
   144|    const properties = data?.properties as { hashed_token?: string } | null | undefined;
   145|    tokenHash = typeof properties?.hashed_token === 'string' ? properties.hashed_token : '';
   146|    if (!tokenHash) {
   147|      return { ok: false, errorMessage: 'generateLink did not return a hashed_token.' };
   148|    }
   149|  } catch (error) {
   150|    return { ok: false, errorMessage: error instanceof Error ? error.message : 'generateLink threw.' };
   151|  }
   152|
   153|  try {
   154|    const anonClient = createClient(supabaseUrl, anonKey, {
   155|      auth: { autoRefreshToken: false, persistSession: false },
   156|    });
   157|    const { data, error } = await anonClient.auth.verifyOtp({ type: 'magiclink', token_hash: tokenHash });
   158|    if (error) {
   159|      return { ok: false, errorMessage: `verifyOtp failed: ${error.message}` };
   160|    }
   161|    const session = data?.session;
   162|    const accessToken = typeof session?.access_token === 'string' ? session.access_token : '';
   163|    const refreshToken = typeof session?.refresh_token === 'string' ? session.refresh_token : '';
   164|    const expiresAt = typeof session?.expires_at === 'number' ? session.expires_at : 0;
   165|    if (!accessToken || !refreshToken) {
   166|      return { ok: false, errorMessage: 'verifyOtp did not return access_token/refresh_token.' };
   167|    }
   168|    return { ok: true, session: { accessToken, refreshToken, expiresAt } };
   169|  } catch (error) {
   170|    return { ok: false, errorMessage: error instanceof Error ? error.message : 'verifyOtp threw.' };
   171|  }
