   174|/** Server-side password grant against the Supabase Auth token endpoint (legacy fallback only). */
   175|async function passwordGrant(supabaseUrl: string, email: string, password: string): Promise<{
   176|  ok: boolean;
   177|  accessToken?: string;
   178|  refreshToken?: string;
   179|  expiresAt?: number;
   180|  errorMessage?: string;
   181|  errorStatus?: number;
   182|}> {
   183|  const endpoint = `${supabaseUrl.replace(/\/+$/, '')}/auth/v1/token?grant_type=password`;
   184|  const anonKey = resolveAnonKey();
   185|  if (!anonKey) {
   186|    return { ok: false, errorMessage: 'Supabase anon key is not configured on the backend.' };
   187|  }
   188|  const controller = new AbortController();
   189|  const timer = setTimeout(() => controller.abort(), 20_000);
   190|  try {
   191|    const response = await fetch(endpoint, {
   192|      method: 'POST',
   193|      headers: {
   194|        'Content-Type': 'application/json',
   195|        apikey: anonKey,
   196|        Authorization: `Bearer ${anonKey}`,
   197|      },
   198|      body: JSON.stringify({ email, password }),
   199|      signal: controller.signal,
   200|    });
   201|    const text = await response.text();
   202|    let parsed: Record<string, unknown> = {};
   203|    try {
   204|      parsed = text ? (JSON.parse(text) as Record<string, unknown>) : {};
   205|    } catch {
   206|      return { ok: false, errorMessage: `Supabase returned non-JSON auth response (HTTP ${response.status}).` };
   207|    }
   208|    if (!response.ok) {
   209|      const message = typeof parsed.error_description === 'string'
   210|        ? parsed.error_description
   211|        : typeof parsed.msg === 'string'
   212|          ? parsed.msg
   213|          : typeof parsed.error === 'string'
   214|            ? parsed.error
   215|            : `Supabase rejected the password grant (HTTP ${response.status}).`;
   216|      return { ok: false, errorMessage: message, errorStatus: response.status };
   217|    }
   218|    const accessToken = typeof parsed.access_token === 'string' ? parsed.access_token : '';
   219|    const refreshToken = typeof parsed.refresh_token === 'string' ? parsed.refresh_token : '';
   220|    const expiresAt = typeof parsed.expires_at === 'number' ? parsed.expires_at : 0;
   221|    if (!accessToken || !refreshToken) {
   222|      return { ok: false, errorMessage: 'Supabase did not return access_token/refresh_token.' };
   223|    }
   224|    return { ok: true, accessToken, refreshToken, expiresAt };
   225|  } catch (error) {
   226|    return { ok: false, errorMessage: error instanceof Error ? error.message : 'Network failure during password grant.' };
   227|  } finally {
   228|    clearTimeout(timer);
   229|  }
