    33|// Non-fatal: logs errors but does not block registration completion.
    34|// ---------------------------------------------------------------------------
    35|
    36|const ROLE_TABLE_MAP: Record<string, string> = {
    37|  investor: 'investors',
    38|  buyer: 'buyers',
    39|  jv_partner: 'jv_partners',
    40|  broker: 'brokers',
    41|  agent: 'agents',
